using System;

[assembly: global::AnimusForge.PolicyEffects.PolicyEffectModuleRegistration(typeof(global::AnimusForge.PolicyEffects.Modules.VillageProductionPctEffectModule))]

namespace AnimusForge.PolicyEffects.Modules;

internal sealed class VillageProductionPctPayload : NumericPolicyEffectPayload
{
}

internal sealed class VillageProductionPctEffectModule
	: NumericPolicyEffectModuleBase<VillageProductionPctPayload>, IModelModifierPolicyEffectModule
{
	private static readonly PolicyEffectModuleDescriptor ModuleDescriptor = new PolicyEffectModuleDescriptor(
		id: "villageProductionPct",
		order: 146,
		legacyIds: Array.Empty<string>(),
		allowedScopes: new[] { PolicyEffectScopes.Kingdom, PolicyEffectScopes.Local, PolicyEffectScopes.Vassal },
		allowedSelectorKinds: new[]
		{
			PolicyEffectTargetKind.Settlement,
			PolicyEffectTargetKind.Clan,
			PolicyEffectTargetKind.Kingdom
		},
		targetKinds: new[] { PolicyEffectTargetKind.Village },
		cueTerms: new[] { PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_0"), PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_1"), PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_2"), PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_3"), PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_4"), PolicyCompatibilityTexts.Get("Module_villageProductionPct_Original_Closeout_5"), "village production", "agriculture", "livestock", "horse breeding", "goods output" },
		retrievalText: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_retrievalText", "The policy directly raises or lowers all native goods output of administratively attached villages of target towns and castles, including village-type products, horses and other livestock, and common grain, cheese and butter batches. It does not change town food stocks, workshop speed or construction power. Goods circulate through native village inventory, villager transport and TradeBound markets."),
		catalogSummary: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_catalogSummary", "Relative native goods output of attached villages"),
		mainInstruction: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_mainInstruction", "Only when the policy directly changes agriculture, livestock, horse breeding, raw materials or grain-goods output in administratively attached villages of target towns or castles, specify a percentage change relative to native village goods output. It affects village-type products including horses and other livestock and common native grain, cheese and butter batches. It does not directly add town food stocks or change workshop speed or construction power. Goods follow native TradeBound logistics; villages have no independent target handles. Do not output module IDs."),
		postprocessRule: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_postprocessRule", "payload must be exactly {\"value\": number}; value must be finite and expresses percentage change relative to final native village goods output. +20 multiplies output by 120%, +100 by 200%; -100 or lower stacked totals set output to zero. It is not a fixed daily item increase. Sum active-policy percentages before scaling both village-type products and common food batches. Lawful parent targets deterministically expand into administratively attached villages; no goods are added directly to any town inventory."),
		payloadPromptSchema: PolicyEffectPayloadSchemas.CreateNumericValueSchema(),
		family: PolicyEffectFamily.Economy,
		executionKind: PolicyEffectExecutionKind.ModelModifier,
		hook: PolicyEffectHook.VillageGoodsProduction,
		aggregation: PolicyEffectAggregationKind.Additive,
		valueUnit: PolicyEffectValueUnit.RelativePercent,
		fundingMode: PolicyEffectFundingMode.InheritPolicy,
		fundingStrategy: PolicyEffectFundingStrategy.Linear,
		payloadSchemaVersion: 1,
		playerDisplayName: PolicyCompatibilityTexts.Get("Module_villageProductionPct_playerDisplayName"),
		editableUnderstandingPrompt: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_editableUnderstandingPrompt", "Village goods output means all actual goods generated by the native production model in administratively attached villages, including village-type products, horses and other livestock, and common grain, cheese and butter batches. Select only if the policy directly changes agriculture, animal husbandry, breeding, gathering, raw-material processing or food-goods output. Do not mistake town food stocks, workshop production speed, construction power or mere trade circulation for village output. Only the production model changes; goods first enter village inventories and circulate through native villager transport and TradeBound markets."),
		editableEvaluationPrompt: PolicyGenerationPromptTexts.Get("Module_villageProductionPct_editableEvaluationPrompt", "The value is a percentage change relative to the final current native village goods output, not a fixed item count. Native base daily village output is low and actual inventory additions use randomized rounding, so positive policies need perceptible intensity. Do not assess clearly effective policies at only +5% to +15%. +20 multiplies output by 1.2, +50 by 1.5, +100 by 2, and -100 sets it to zero. Mild tools, road maintenance or seasonal support usually use +20% to +40%, or -10% to -20% for negatives. Explicit agricultural, husbandry or breeding institutions use about +40% to +80%, or -20% to -40%. Large irrigation, land reform or strong production reforms use about +80% to +150%; forced requisition, severe labor loss or disasters use -40% to -70%. Extreme positive policies changing regional economic structure may reach +150% to +250%; devastating disasters or total plunder use -70% to -100%. Add policies first; the multiplier minimum is 0 and there is no extra positive hard cap, but negative assessments must not be below -100%."),
		allowCrossKingdomTargets: true);

	public override PolicyEffectModuleDescriptor Descriptor => ModuleDescriptor;

	public System.Collections.Generic.IReadOnlyList<PolicyEffectModelContribution> BuildModelContributions(
		PolicyEffectPreparedInstance preparedInstance)
		=> PolicyEffectModuleRuntimeAdapters.BuildNumericModelContributions(this, preparedInstance);
}
